/* ── SCM_ADM_API_M — 화면 전용 API · upsert · 키 API_ID (PK) · 1행 */
MERGE INTO SCM_MGR.SCM_ADM_API_M T
USING (SELECT 'SCP0127_init_SEARCH' API_ID, 'PROC_SELECT' API_TP_CD, '/' API_MSG_ID, NULL API_MSG_DESC, 'PKG_SCP0127.P_SCP0127_GET_SEARCH_INFO' API_URL, 'Y' USE_YN FROM DUAL) S
   ON (NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'))
 WHEN MATCHED THEN UPDATE SET T.API_TP_CD = S.API_TP_CD, T.API_MSG_ID = S.API_MSG_ID, T.API_MSG_DESC = S.API_MSG_DESC, T.API_URL = S.API_URL, T.USE_YN = S.USE_YN, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
      WHERE DECODE(T.API_TP_CD, S.API_TP_CD, 0, 1) = 1 OR DECODE(T.API_MSG_ID, S.API_MSG_ID, 0, 1) = 1 OR DECODE(T.API_MSG_DESC, S.API_MSG_DESC, 0, 1) = 1 OR DECODE(T.API_URL, S.API_URL, 0, 1) = 1 OR DECODE(T.USE_YN, S.USE_YN, 0, 1) = 1
 WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
      VALUES (S.API_ID, S.API_TP_CD, S.API_MSG_ID, S.API_MSG_DESC, S.API_URL, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE);

