       UNION ALL SELECT 'SCP0127' MNU_ID, 'main' SHT_NM, 'DELETE' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0127' MNU_ID, 'main' SHT_NM, 'INSERT' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0127' MNU_ID, 'main' SHT_NM, 'SAVE' MNU_BTN_CD, 'P_SCP0127_SAVE' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0127' MNU_ID, 'main' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_SCP0127_GET' API_ID, 'Y' USE_YN FROM DUAL) S
   ON (NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~'))
