  FROM (SELECT 'DEFAULT_FLAG' SQL_ID, 'ALL' MDU_DIVS_CD, '[공통] AS-IS UP_FX_GetCommonDataList @Code=''DEFAULT_FLAG''' SQL_NM, 'SELECT SEGMENT1 as code , SEGMENT2 as name FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''DEFAULT_FLAG'' ORDER BY DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
