SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Division_SCP' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP] AS-IS UP_FX_GetCommonDataList_SCP @Code=''Division''' SQL_NM, 'SELECT A.DIVISION_ID AS CODE , A.DIVISION_ID || '' '' || A.DIVISION_NAME AS NAME , A.DAILY_PLAN_PERIOD , A.VALID_YN , A.CREATION_DATE , A.CREATED_BY , A.LAST_UPDATE_DATE , A.LAST_UPDATED_BY , A.ATTRIBUTE1 , A.ATTRIBUTE2 , A.ATTRIBUTE3 , A.ATTRIBUTE4 , A.ATTRIBUTE5 , A.ATTRIBUTE6 , A.ATTRIBUTE7 , A.ATTRIBUTE8 , A.ATTRIBUTE9 , A.ATTRIBUTE10 FROM SCM_MST_DIVISION A WHERE A.DIVISION_ID IN ( SELECT U.UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M U WHERE U.UNIT_TP_CD = ''D'' AND U.USE_YN = ''Y'' AND U.USER_ID = @sesUserId AND U.USER_GR_ID IN ( SELECT G.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M G WHERE G.USER_ID = @sesUserId AND G.USE_YN = ''Y'' ) AND ( NVL(TRIM(@mnuId), ''ALL'') = ''ALL'' OR U.USER_GR_ID IN ( SELECT M.USER_GR_ID FROM SCM_ADM_USER_GR_MNU_MPG_M M WHERE M.MNU_ID = @mnuId AND M.USE_YN = ''Y'' ) ) ) AND A.VALID_YN = ''Y'' ORDER BY UPPER(A.ATTRIBUTE1)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
